#include "native-surface-heat.hpp"
#include <fstream>
#include <iostream>
using namespace dome;using namespace dome::detail;
int main(int argc,char**argv)try{
 if(argc!=3)return 2;const auto scene=Scene::load(argv[1]);uint64_t reference=0;for(const auto&o:scene.objects())if(o.deformation&&o.deformation->skeleton){if(reference)throw std::runtime_error("One genuine fitted rig input required");reference=o.id;}const auto&ref=scene.object(reference);const auto&roles=ref.deformation->humanoid->joints;const auto&rig=*ref.deformation->skeleton;const std::function<bool()>never;weight_surface::Budget w{0,500'000'000,never};const auto world=scene.world_matrix(reference);auto shift=AffineTransform{}.matrix();for(size_t k=0;k<3;++k)shift[12+k]=-world.matrix()[12+k];const AffineTransform origin(shift);auto profile=declared_weight_profile(rig,w,DeclaredRigGeometry::NativeBoneAxes);for(auto&s:profile.segments){auto f=[&](std::array<double,3>a){auto p=skin_affine_point(origin*world,{float(a[0]),float(a[1]),float(a[2])});return std::array<double,3>{p.x,p.y,p.z};};s.head=f(s.head);s.tail=f(s.tail);}const auto head=roles.at("head");HeatJointMask branch{},eyes{};for(auto role:{"neck","head","leftEye","rightEye"})if(roles.contains(role)){auto j=roles.at(role);branch[j/64]|=uint64_t(1)<<(j%64);}for(auto role:{"leftEye","rightEye"}){auto j=roles.at(role);eyes[j/64]|=uint64_t(1)<<(j%64);}nlohmann::json report=nlohmann::json::array();
 for(const auto&o:scene.objects())if(o.mesh_active&&o.painted){if(o.appearance||o.material_bindings||(o.deformation&&o.deformation->skin))throw std::runtime_error("Actual current geometry/roles only, no original/skin source");SkinGeometryWork geom(w.maximum-w.used,never);auto before=geom.remaining();const auto metric=skin_world_mesh(o.painted->mesh(),origin*scene.world_matrix(o.id),geom);w.step(before-geom.remaining());HeatBindingOptions opts;opts.maximum_work=w.maximum-w.used;opts.maximum_bytes=128u*1024u*1024u;std::vector<std::vector<Vec3>>deltas;if(o.deformation&&o.deformation->morphs)for(const auto&t:o.deformation->morphs->targets)deltas.push_back(t.delta);auto sewn=geometric_boundary_sewing(o.painted->mesh(),deltas,128u*1024u*1024u,w);DeclaredWeightPart part;part.object=o.id;part.geometric_row_groups=std::move(sewn.groups);const auto intent=declared_weight_intent(o,part,profile,opts,w,DeclaredSupportPolicy::UniqueSourceWitnesses,metric,ref.deformation);HeatJointMask aggregate{};for(const auto&m:intent.masks(o))for(size_t k=0;k<4;++k){w.step();aggregate[k]|=m[k];}bool primary=aggregate[head/64]&(uint64_t(1)<<(head%64)),ocular=aggregate!=HeatJointMask{};std::vector<std::string>labels;for(size_t k=0;k<4;++k){primary&=(aggregate[k]&~branch[k])==0;ocular&=(aggregate[k]&~eyes[k])==0;}for(const auto&[name,j]:roles)if(aggregate[j/64]&(uint64_t(1)<<(j%64)))labels.push_back(name);report.push_back({{"object",o.id},{"name",o.name},{"primary",primary},{"ocular",ocular},{"nearest_geometric_roles",labels}});}
 std::ofstream(argv[2])<<nlohmann::json{{"parts",report},{"work",w.used}}.dump(2);return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
